    protected void setValues()
    {
        InventSum       iSum;
        Map             itemIDs = new Map(Types::String,Types::Real);
        Set             inventDims = new Set(Types::String);
        SetEnumerator   sEnum;
        ItemId          itemId;
        str             itemString = '';
        str             itemImageStr = '';
        real            physicalInvent;
        real            physicalAvail;
        MapEnumerator   mEnum;
        WHSLicensePlate licensePlate = common;
        WMSLocationId   location;
        InventLocationId locId;
        InventDim		InventDim;
        MobCarts		carts;

        while select InventDim
        where InventDim.LicensePlateId == licensePlate.LicensePlateId
			join iSum
				where iSum.InventDimId     == InventDim.InventDimId    &&
						iSum.Closed          == NoYes::No && iSum.PhysicalInvent
        {
            itemIDs.insert(iSum.ItemId, (itemIDs.exists(iSum.ItemId) ? itemIDs.lookup(iSum.ItemId) : 0) + iSum.PhysicalInvent);
            itemId = iSum.ItemId;
            physicalInvent += iSum.PhysicalInvent;
            physicalAvail += iSum.availPhysicalCalculated();
            location = inventDim.wMSLocationId;
            locId = InventDim.InventLocationId;
            inventDims.add(inventDim.inventDimId);
        }

        mEnum = itemIDs.getEnumerator();
        while(mEnum.moveNext())
        {
            itemString += (itemString ? "@MobileWMS:lineBreak" : '') + mEnum.currentKey() + ': ' + MobHelper::formatItemQty(mEnum.currentValue(), inventTable::find(mEnum.currentKey()).inventUnitId()) + ' ' +inventTable::find(mEnum.currentKey()).inventUnitId();
            itemImageStr += (itemImageStr ? ',' : '') + mEnum.currentKey();
        }

        super();
        if (itemIDs.elements() == 1)
        {
            if (inventDims.elements() == 1)
            {
                sEnum = inventDims.getEnumerator();
                sEnum.moveNext();
                InventDim.InventDimId = sEnum.current();
                //imageId = MobHelper::imageIDFromDocuref(MobHelper::FindItemDocuref(itemId,inventSum.InventDimId));
            }
            imageId = MobHelper::imageIDFromDocuref(MobHelper::FindItemDocuref(itemId,InventDim.InventDimId));
            fieldsToAdd.insert(strLwr(new DictField(tablenum(InventSum), fieldnum(InventSum, ItemId)).name()), itemid);
            fieldsToAdd.insert(MobConstants::ItemNumber(), itemid);
        }
        else
        {
            //imageId = resourceStr(MobPalletWithItemsIcon);
            imageID = itemImageStr;
        }

        carts = MobCarts::FindByLocation(locId,location);

        displayLine1 = new DictField(tablenum(WHSLicensePlate), fieldnum(WHSLicensePlate, LicensePlateId)).Label() + ' ' + licensePlate.LicensePlateId;
        displayLine3 = itemString;
        displayLine2 = "@MobileWMS:Cart" +' ' +carts.CartID + '('+ new DictField(tablenum(WMSLocation), fieldnum(WMSLocation, WMSLocationId)).Label() + ' ' + location + ')';
        backendId          = tableStr(WHSLicensePlate) + '/' + fieldStr(WHSLicensePlate, LicensePlateId) + '/' + licensePlate.LicensePlateId;
        fieldsToAdd.insert(strLwr(new DictField(tablenum(WHSLicensePlate), fieldnum(WHSLicensePlate, LicensePlateId)).name()), licensePlate.LicensePlateId);
        fieldsToAdd.insert(MobConstants::Quantity(), strFmt('%1', real2int(physicalAvail)));
        fieldsToAdd.insert(extendedTypeStr(InventQtyTotal), strFmt('%1', real2int(physicalInvent)));
        fieldsToAdd.insert(fieldStr(MobCarts,PickMode),carts.PickMode ? "@MobileWMS:PickMode" : "@MobileWMS:UnloadMode");

    }
